"use strict";

const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',issues:'<path d="M9 5H5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-4"/><rect x="9" y="2" width="6" height="6" rx="2"/><path d="m7 14 2 2 4-4m2 5h2"/>',people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',chart:'<path d="M3 3v18h18M7 15v2m5-8v8m5-12v12"/>',database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14a9 3 0 0 0 18 0V5M3 12a9 3 0 0 0 18 0"/>',shield:'<path d="m12 3 8 4v6c0 5-8 9-8 9s-8-4-8-9V7z"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',alert:'<path d="m10.3 3-8.7 15A2 2 0 0 0 3.3 21h17.4a2 2 0 0 0 1.7-3L13.7 3a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',link:'<path d="m10 13 4-4m-5 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 1a4 4 0 0 1 6 0l-5 5a4 4 0 0 1-6 0"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8m-8 4h6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',layers:'<path d="m12 3 10 6-10 6L2 9zM2 13l10 6 10-6M2 17l10 6 10-6"/>',activity:'<path d="M2 12h5l3-9 4 18 3-9h5"/>',branch:'<circle cx="6" cy="5" r="2"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="7" r="2"/><path d="M6 7v10m0-3c7 0 12 0 12-5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',refresh:'<path d="M20 7a8 8 0 1 0 0 10M20 3v5h-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',spark:'<path d="M12 3v4m0 10v4M3 12h4m10 0h4M6 6l3 3m6 6 3 3M6 18l3-3m6-6 3-3"/>'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.database}</svg>`;
const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=value=>Number(value||0).toLocaleString('en-US');
const human=value=>String(value||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const issueNames={possible_ghost_access:'Leaver account still enabled',cross_system_conflict:'Conflicting values',duplicate_identifier:'Duplicate identifier',duplicate_profile:'Duplicate profile',invalid_code:'Invalid code',invalid_date:'Invalid date',missing_value:'Missing required value',out_of_date_record:'Out-of-date record',temporal_inconsistency:'Contradictory dates'};
const sourceNames={core_hr:'Core HR',payroll:'Payroll',learning:'Learning',access_directory:'Access directory'};
const reportNames={active_headcount_dubai:'Active employees in Dubai',leaver_enabled_accounts:'Leavers with enabled accounts',payroll_reconciliation:'Payroll reconciliation exceptions'};
const pretty=value=>value===null||value===undefined||value===''?'Missing':String(value);
function resolvedValue(res){return res.field==='termination_date'&&res.status==='resolved'&&res.value==null?'No end date':pretty(res.value)}
function comparisonHeading(issue){return issue.issue_type==='possible_ghost_access'?'Lifecycle evidence':human(issue.field)}
const initials=name=>String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const badge=(text,kind='neutral')=>`<span class="badge ${E(kind)}">${E(text)}</span>`;
const priority=band=>badge(band,String(band).toLowerCase());
const sourceTag=source=>`<span class="source-tag">${E(sourceNames[source]||human(source))}</span>`;
const dateLabel=iso=>new Date(`${iso}T00:00:00`).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const shortID=id=>String(id||'').slice(-10);
const statusHTML=status=>`<span class="status-cell ${E(status)}"><i></i>${E({open:'Awaiting review',approve:'Approved proposal',reject:'Rejected proposal',investigate:'Investigating'}[status]||human(status))}</span>`;
const empty=(title,text,action='')=>`<div class="empty-state"><div class="empty-icon">${icon('issues',25)}</div><h2>${E(title)}</h2><p>${E(text)}</p>${action}</div>`;
const notice=(text,kind='',symbol='info')=>`<div class="notice ${kind}">${icon(symbol,17)}<div>${text}</div></div>`;
const download=(filename)=>`/api/download?run=${encodeURIComponent(S.run)}&file=${encodeURIComponent(filename)}`;
const S={run:localStorage.getItem('hr-run')||'development',route:'overview',overview:null,bootstrap:null,issuePage:1,employeePage:1,issueFilter:'',employeeFilter:'',drawer:null,simulations:new Map(),epoch:0,reports:null,sourceData:null,job:null,referencePreview:null,referenceRevision:0,uploadSources:[],uploadReady:true,uploadRevision:0};

async function api(path,params={},body=null){
  const url=new URL(path,location.origin);url.searchParams.set('run',S.run);
  Object.entries(params).forEach(([key,value])=>{if(value!==''&&value!==null&&value!==undefined)url.searchParams.set(key,value)});
  const options=body===null?{}:{method:'POST',headers:{'Content-Type':'application/json','X-HR-Workspace':S.bootstrap.csrf},body:JSON.stringify({...body,run:S.run})};
  const response=await fetch(url,options);let data;try{data=await response.json()}catch{throw new Error('The workspace did not return a valid response. Please refresh.')}
  if(!response.ok)throw new Error(data.error||'The action could not complete.');return data;
}
function toast(message,error=false){document.querySelector('#toast-root').innerHTML=`<div class="toast ${error?'error':''}">${icon(error?'alert':'check',17)}${E(message)}</div>`;setTimeout(()=>document.querySelector('#toast-root').replaceChildren(),5000)}
function heading(title,description,actions='',eyebrow='WORKSPACE'){return `<div class="page-heading"><div><span class="eyebrow">${E(eyebrow)}</span><h1>${E(title)}</h1><p>${E(description)}</p></div><div class="heading-actions">${actions}</div></div>`}
function loading(){return '<div class="loading-state"><span class="spinner"></span><h2>Loading the analysis</h2><p>Preparing the records and evidence for this view.</p></div>'}
function renderNav(){const nav=[['overview','grid','Overview'],['issues','issues','Issue queue'],['employees','people','Employee matching'],['reports','chart','Reports & data trust'],['sources','database','Sources & analysis'],['audit','shield','Decisions & exports']];document.querySelector('#navigation').innerHTML=nav.map(([key,symbol,label])=>`<button class="nav-item ${S.route===key?'active':''}" data-route="${key}" ${S.route===key?'aria-current="page"':''}>${icon(symbol,17)}<span>${label}</span>${key==='issues'&&S.overview?`<span class="nav-counter">${N(S.overview.summary.issue_count)}</span>`:''}</button>`).join('');document.querySelector('#breadcrumb-current').textContent=nav.find(n=>n[0]===S.route)?.[2]||'Overview';}
function renderRuns(){document.querySelector('#run-select').innerHTML=S.bootstrap.runs.map(r=>`<option value="${E(r.id)}" ${r.id===S.run?'selected':''}>${E(r.label)}</option>`).join('')}
async function loadRun(){document.querySelector('#main').innerHTML=loading();S.overview=await api('/api/overview');for(const source of S.overview.sources)sourceNames[source.source_system]=source.name;document.querySelector('#topbar-date').textContent=`As of ${dateLabel(S.overview.summary.as_of)}`;renderRuns();renderNav();await renderPage()}
function navigate(route){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(location.hash===`#${route}`){S.route=route;renderPage()}else location.hash=route;}
async function renderPage(){const epoch=++S.epoch;renderNav();const main=document.querySelector('#main');try{
  if(S.route==='overview')main.innerHTML=overviewPage();
  else if(S.route==='issues'){main.innerHTML=issuesPage();await refreshIssues()}
  else if(S.route==='employees'){main.innerHTML=employeesPage();await refreshEmployees()}
  else if(S.route==='reports'){const reports=await api('/api/reports');if(epoch!==S.epoch)return;S.reports=reports;main.innerHTML=reportsPage()}
  else if(S.route==='sources'){const result=await api('/api/sources');if(epoch!==S.epoch)return;S.sourceData=result;main.innerHTML=sourcesPage(result)}
  else if(S.route==='audit'){const result=await api('/api/audit');if(epoch!==S.epoch)return;main.innerHTML=auditPage(result)}
  else{S.route='overview';main.innerHTML=overviewPage()}
}catch(error){if(epoch===S.epoch)main.innerHTML=empty('This view could not load',error.message,'<button class="button" data-action="retry">Try again</button>')}}

function stat(label,value,note,symbol,alert=false){return `<div class="stat-card ${alert?'alert':''}"><div class="stat-top"><span class="stat-label">${E(label)}</span><span class="stat-icon">${icon(symbol,16)}</span></div><div class="stat-value">${N(value)}</div><div class="stat-note">${alert?'<span class="tiny-dot"></span>':''}${E(note)}</div></div>`}
function topIssueRows(issues){return issues.map(i=>`<tr data-issue="${E(i.issue_id)}" tabindex="0" role="button" aria-label="Review ${E(issueNames[i.issue_type])} for ${E(i.employee_name)}"><td>${priority(i.priority_band)}</td><td><div class="cell-title">${E(issueNames[i.issue_type]||human(i.issue_type))}</div><div class="cell-sub">${E(human(i.field))} · ${E(i.employee_name)}</div></td><td>${sourceTag(i.source_system)}</td><td>${icon('chevron',14)}</td></tr>`).join('')}
function overviewPage(){const d=S.overview,s=d.summary,counts=s.identity_status_counts,total=s.source_record_count,linked=counts.linked||0,pct=linked/Math.max(total,1)*100,review=(counts.review_required||0)/Math.max(total,1)*100;const categories=Object.entries(s.issues_by_type).sort((a,b)=>b[1]-a[1]);const max=Math.max(...categories.map(x=>x[1]),1);
return heading('Data quality overview','Review discrepancies across your HR systems. See the evidence and the effect of each proposed correction.',`<span class="complete-pill">${icon('check',13)} Analysis complete</span><a class="button" href="${download('issues.csv')}">${icon('download',15)} Export issues</a>`)+
`<div class="stat-grid">${stat('Source records',total,`${d.sources.length} connected source extracts`,'database')}${stat('Awaiting a decision',d.open_count,'Ranked by business consequence','issues')}${stat('Supported proposals',s.proposed_corrections,'Evidence-backed values to review','check')}${stat('Critical access cases',d.priority_counts.P0||0,'Potential exposure after leaving','shield',true)}</div>
<div class="grid-main"><section class="card"><div class="card-header"><div><h2>Start with the highest impact</h2><p>The most urgent findings across the workspace</p></div><button class="text-link" data-route="issues">View all issues ${icon('arrow',14)}</button></div><div class="table-wrap"><table><thead><tr><th>Priority</th><th>Finding / employee</th><th>Source</th><th></th></tr></thead><tbody>${topIssueRows(d.top_issues)}</tbody></table></div><div class="card-note">Priority combines business severity and declared downstream dependencies.</div></section>
<section class="card"><div class="card-header"><div><h2>Identity resolution</h2><p>How source records link across systems</p></div>${icon('link',17)}</div><div class="card-body"><div class="donut-layout"><div class="donut" style="background:conic-gradient(#5d9c83 0 ${pct}%,#e3bb72 ${pct}% ${pct+review}%,#e4ece8 ${pct+review}% 100%)"><div class="donut-center"><strong>${pct.toFixed(1)}<span style="font-size:14px">%</span></strong><small>records linked</small></div></div><div class="legend">${[['Linked','linked','linked'],['Needs review','review_required','review'],['Single source','single_source','single']].map(([label,key,kind])=>`<div class="legend-item"><span><i class="legend-dot ${kind}"></i>${label}</span><b>${N(counts[key])}</b></div>`).join('')}</div></div><button class="button" style="width:100%" data-route="employees">Inspect employee matches ${icon('arrow',14)}</button></div><div class="card-note">Linked share measures coverage, not matching accuracy.</div></section></div>
<div class="grid-main"><section class="card"><div class="card-header"><div><h2>Findings by category</h2><p>Every finding carries a rule and source evidence</p></div>${badge(`${N(s.issue_count)} total`)}</div><div class="card-body">${categories.map(([key,value])=>`<div class="bar-row"><div class="bar-caption"><span>${E(issueNames[key]||human(key))}</span><span>${N(value)}</span></div><div class="bar-track"><div class="bar-fill ${key==='possible_ghost_access'?'critical':key==='cross_system_conflict'?'warm':''}" style="width:${value/max*100}%"></div></div></div>`).join('')}</div></section>
<section class="card"><div class="card-header"><div><h2>Reports in view</h2><p>Confirmed results, with uncertainty disclosed</p></div><button class="text-link" data-route="reports">Explore ${icon('arrow',14)}</button></div>${Object.entries(d.reports).map(([key,r])=>`<div class="report-strip"><div><h3>${E(reportNames[key])}</h3><div class="tag-row">${(r.sources||[]).map(sourceTag).join('')}</div><span class="subtle-note">${N(r.unresolved_count)} cases require review</span></div><div class="count">${r.availability==='available'?N(r.value):'—'}<small>${E(r.unit==='distinct_people'?'distinct people':r.unit==='payroll_profiles'?'payroll profiles':'enabled accounts')}</small></div></div>`).join('')}<div class="card-note">A correction preview recalculates these reports in isolation.</div></section></div>
<section class="card"><div class="card-header"><div><h2>Source coverage</h2><p>Read-only extracts used in this analysis</p></div><button class="text-link" data-route="sources">Manage sources ${icon('arrow',14)}</button></div><div class="card-body"><div class="source-grid" style="margin-bottom:0">${d.sources.map(source=>`<div class="coverage-row" style="border:0"><span class="source-icon">${icon(source.source_system==='access_directory'?'shield':source.source_system==='learning'?'layers':'database',17)}</span><div class="coverage-name">${E(source.name)}<small>${N(source.records)} records · ${source.fields} fields</small></div><span class="coverage-status">${icon(source.status==='loaded'?'check':'alert',12)} ${source.status==='loaded'?'Loaded':'Review'}</span></div>`).join('')}</div></div></section>`;
}

function issuesPage(){const s=S.overview.summary;return heading('Issue queue','An evidence-backed review list. Approving a proposal records your decision; it never changes source data.',`<a class="button" href="${download('issues.csv')}">${icon('download',15)} Export issues</a>`)+`<section class="card"><div class="tabs" role="tablist" aria-label="Finding readiness">${[['','All findings',s.issue_count],['proposed','Supported proposals',s.proposed_corrections],['investigate','Needs investigation',s.issue_count-s.proposed_corrections]].map(([key,label,count])=>`<button class="tab ${S.issueFilter===key?'active':''}" data-action="issue-tab" data-value="${key}" role="tab" aria-selected="${S.issueFilter===key}">${label}<span class="tab-count">${N(count)}</span></button>`).join('')}</div><div class="filters"><div class="search-input">${icon('search',15)}<input class="input" id="issue-search" aria-label="Search issues" placeholder="Search employee, finding or source ID…"></div><select class="input filter-select" id="issue-priority" aria-label="Filter by priority"><option value="">All priorities</option>${['P0','P1','P2','P3'].map(p=>`<option>${p}</option>`).join('')}</select><select class="input filter-select" id="issue-source" aria-label="Filter by source"><option value="">All sources</option>${S.overview.sources.map(source=>`<option value="${E(source.source_system)}">${E(source.name)}</option>`).join('')}</select><select class="input filter-select" id="issue-type" aria-label="Filter by issue category"><option value="">All categories</option>${Object.entries(issueNames).map(([key,value])=>`<option value="${key}">${value}</option>`).join('')}</select><select class="input filter-select" id="issue-status" aria-label="Filter by review status"><option value="">All review states</option><option value="open">Awaiting review</option><option value="approve">Approved proposals</option><option value="reject">Rejected proposals</option><option value="investigate">Investigating</option></select></div><div id="issues-results"></div></section>`}
function pageFooter(data,list){const start=data.total?(data.page-1)*data.size+1:0;return `<div class="table-footer"><span>${start}–${Math.min(data.page*data.size,data.total)} of ${N(data.total)} ${list==='issues'?'findings':'employee groups'}</span><div class="pagination"><button data-action="paginate" data-list="${list}" data-value="${data.page-1}" ${data.page<=1?'disabled':''} aria-label="Previous page">${icon('left',13)}</button><span>Page ${data.page} of ${data.pages}</span><button data-action="paginate" data-list="${list}" data-value="${data.page+1}" ${data.page>=data.pages?'disabled':''} aria-label="Next page">${icon('chevron',13)}</button></div></div>`}
async function refreshIssues(){const params={page:S.issuePage,size:20,recommendation_status:S.issueFilter,q:document.querySelector('#issue-search')?.value||'',priority_band:document.querySelector('#issue-priority')?.value||'',source_system:document.querySelector('#issue-source')?.value||'',issue_type:document.querySelector('#issue-type')?.value||'',review_status:document.querySelector('#issue-status')?.value||''};const data=await api('/api/issues',params);const element=document.querySelector('#issues-results');if(!element)return;element.innerHTML=data.items.length?`<div class="table-wrap"><table><thead><tr><th>Priority</th><th>Finding</th><th>Employee</th><th>Source</th><th>Observed → proposed</th><th>Priority & effect</th><th>Review state</th></tr></thead><tbody>${data.items.map(i=>`<tr data-issue="${E(i.issue_id)}" role="button" tabindex="0" aria-label="Review ${E(issueNames[i.issue_type])} for ${E(i.employee_name)}"><td>${priority(i.priority_band)}</td><td><div class="cell-title">${E(issueNames[i.issue_type]||human(i.issue_type))}</div><div class="cell-sub">${E(human(i.field))}</div></td><td><div class="employee-cell"><span class="avatar">${E(initials(i.employee_name))}</span><div><div class="cell-title">${E(i.employee_name)}</div><div class="cell-sub">…${E(shortID(i.source_id))}</div></div></div></td><td>${sourceTag(i.source_system)}</td><td><div class="value-change"><span class="value-before" title="${E(pretty(i.observed_value))}">${E(pretty(i.observed_value))}</span>${icon('arrow',12)}<span class="value-after" title="${E(i.suggested_value||'Requires investigation')}">${E(i.suggested_value||'Investigate')}</span></div></td><td><span class="priority-score">${i.priority_score}<small>pts</small></span><div class="cell-sub impact-summary">${E(impactSummary(i))}</div></td><td>${statusHTML(i.review_status)}</td></tr>`).join('')}</tbody></table></div>${pageFooter(data,'issues')}`:empty('No findings match these filters','Try another search or clear a filter to see more of the issue queue.');}

function employeesPage(){return heading('Employee matching','Inspect the same person across systems, including separate employments and records that need identity review.',`<a class="button" href="${download('employees.csv')}">${icon('download',15)} Export matches</a>`)+`<section class="card"><div class="filters"><div class="search-input">${icon('search',15)}<input class="input" id="employee-search" aria-label="Search employee matches" placeholder="Search a name, employee group or source ID…"></div><select class="input filter-select" id="employee-status" aria-label="Filter employee match status"><option value="">All match states</option><option value="linked" ${S.employeeFilter==='linked'?'selected':''}>Linked records</option><option value="review_required" ${S.employeeFilter==='review_required'?'selected':''}>Needs identity review</option><option value="single_source">Single source</option></select></div><div id="employees-results"></div></section><div class="section-space">${notice('Evidence scores rank matching signals. They are not probabilities of a correct match. Ambiguous records retain separate provisional identities.','neutral')}</div>`}
async function refreshEmployees(){const data=await api('/api/employees',{page:S.employeePage,size:20,q:document.querySelector('#employee-search')?.value||'',status:document.querySelector('#employee-status')?.value||''});const element=document.querySelector('#employees-results');if(!element)return;element.innerHTML=data.items.length?`<div class="table-wrap"><table><thead><tr><th>Employee / group</th><th>Source systems</th><th>Records</th><th>Matching state</th><th>Findings</th><th></th></tr></thead><tbody>${data.items.map(p=>`<tr data-employee="${E(p.person_id)}" role="button" tabindex="0" aria-label="Inspect employee ${E(p.name)}"><td><div class="employee-cell"><span class="avatar">${E(initials(p.name))}</span><div><div class="cell-title">${E(p.name)}</div><div class="cell-sub">${E(p.person_id)}</div></div></div></td><td><div class="tag-row">${p.sources.map(sourceTag).join('')}</div></td><td>${p.record_count}</td><td>${badge(p.status==='linked'?'Linked':p.status==='review_required'?'Needs review':'Single source',p.status==='linked'?'green':p.status==='review_required'?'amber':'neutral')}</td><td>${p.issue_count?badge(`${p.issue_count} findings`,'amber'):'<span class="muted">—</span>'}</td><td>${icon('chevron',14)}</td></tr>`).join('')}</tbody></table></div>${pageFooter(data,'employees')}`:empty('No employee groups found','Try a different name or source identifier.');}

function readinessLabel(state){return {checks_passed:'Checks passed · human sign-off needed',review_required:'Review required',unavailable:'Unavailable'}[state]||'Run a new analysis for readiness'}
function assuranceHTML(r){
  const a=r.assurance;
  if(!a)return notice('This saved analysis predates report assurance. Run a new analysis to calculate readiness and scores.','warning');
  return `<div class="assurance-panel"><div class="assurance-top">${badge(readinessLabel(a.readiness),a.readiness==='checks_passed'?'green':'amber')}<span class="score-label">Trust score <strong>${a.trust_score==null?'Not measured':E(a.trust_score)+' / 100'}</strong></span></div><p class="text-small muted">Evidence coverage: ${N(a.assessed_cases)} of ${N(a.population_count)} cases assessed. This score is not a probability that the report is correct.</p><details><summary>Score formula & reporting readiness</summary><div class="details-body"><p>${E(a.score_formula)}</p>${a.readiness_reasons.map(reason=>`<p style="margin-top:8px">${E(reason)}</p>`).join('')}</div></details></div>`;
}
function impactSummary(issue){
  const m=issue.measured_impact;
  if(m?.status!=='calculated')return 'Needs investigation';
  const changed=Object.entries(m.reports).filter(([,r])=>r.delta||r.unresolved_after!==r.unresolved_before);
  return changed.length?changed.map(([key,r])=>`${{active_headcount_dubai:'Headcount',leaver_enabled_accounts:'Access exceptions',payroll_reconciliation:'Payroll exceptions'}[key]||human(key)} ${r.delta>0?'+':''}${r.delta}${r.unresolved_after!==r.unresolved_before?' · review cases '+(r.unresolved_after-r.unresolved_before):''}`).join('; '):'Reports unchanged';
}
function reportUnit(key){return {active_headcount_dubai:'confirmed distinct people',leaver_enabled_accounts:'potential account exceptions',payroll_reconciliation:'profiles with established discrepancies'}[key]||'confirmed cases'}
function reportsPage(){return heading('Reports & data trust','Inspect the evidence, reporting readiness and unresolved cases behind each result.','','REPORT ASSURANCE')+`
<div class="page-tabs tabs" role="tablist"><button class="tab active" data-action="report-tab" data-value="results" role="tab" aria-selected="true">Report results</button><button class="tab" data-action="report-tab" data-value="quality" role="tab" aria-selected="false">Field quality & trust</button></div>
<div id="report-results"><div class="report-grid">${Object.entries(S.reports).map(([key,r])=>`<section class="card report-card"><div class="card-title">${icon(key==='active_headcount_dubai'?'people':key==='payroll_reconciliation'?'chart':'shield',18)}<h2>${E(reportNames[key]||human(key))}</h2></div><div class="report-count">${r.availability==='available'?N(r.value):'—'}</div><div class="report-unit">${E(reportUnit(key))} · as of ${dateLabel(r.as_of)}</div><p class="definition">${E(r.definition)}</p><div class="tag-row">${(r.sources||[]).map(sourceTag).join('')}${badge(r.availability==='available'?'Inputs loaded':r.availability,r.availability==='available'?'neutral':'amber')}</div>${assuranceHTML(r)}<div class="report-card-foot"><span class="subtle-note" style="margin-top:0">${N(r.unresolved_count)} cases require review</span><button class="button button-small" data-action="report-detail" data-value="${E(key)}">View evidence ${icon('arrow',13)}</button></div></section>`).join('')}</div>
<section class="card question-box"><div class="card-title">${icon('search',19)}<h2>Ask about these reports</h2></div><p class="muted text-small" style="margin-top:7px">Three supported questions, answered locally from calculated reports with their sources and readiness.</p><form id="question-form" class="question-form"><input type="text" id="question-input" aria-label="Question about employee reports" placeholder="How many active employees in Dubai?" required><button class="button button-primary" type="submit">Get answer ${icon('arrow',15)}</button></form><div class="question-examples">${[['How many active employees in Dubai?','Active employees in Dubai'],['How many leavers have enabled accounts?','Leavers with enabled accounts'],['How many payroll profiles have conflicts?','Payroll reconciliation']].map(([question,label])=>`<button data-action="example-question" data-value="${E(question)}">${E(label)} ${icon('arrow',11)}</button>`).join('')}</div><div id="question-answer"></div></section></div><div id="report-quality" hidden>${qualityTable()}</div>`}
function qualityCell(value){if(value===''||value===null)return '<span class="muted">Not measured</span>';const pct=Number(value)*100;return `<div class="quality-cell"><span>${pct.toFixed(1)}%</span><div class="quality-bar"><i style="width:${Math.max(0,Math.min(100,pct))}%"></i></div></div>`}
function qualityTable(){return `<section class="card"><div class="card-header"><div><h2>Measured field quality & trust</h2><p>Trust score uses validity and issue-free percentage; required fields also use completeness</p></div><a class="button button-small" href="${download('field_trust.csv')}">${icon('download',14)} Export</a></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Field</th><th>Trust / 100</th><th>Records</th><th>Complete</th><th>Valid when present</th><th>Without detected issues</th></tr></thead><tbody>${S.overview.trust.map(r=>`<tr><td>${sourceTag(r.source_system)}</td><td class="cell-title">${E(human(r.field))}</td><td title="${E(r.score_formula||'Run a new analysis for scores')}">${r.trust_score==null||r.trust_score===''?'Not measured':E(r.trust_score)}</td><td>${N(r.records)}</td><td>${qualityCell(r.completeness)}</td><td>${qualityCell(r.validity_of_present)}</td><td>${qualityCell(r.issue_free_fraction)}</td></tr>`).join('')}</tbody></table></div><div class="card-note">Scores describe observed quality, not correctness probabilities. Optional blanks are shown in completeness but do not lower the trust score. Optional fields without observations are not scored.</div></section>`}

function impactReportHTML(key,r){const available=r.availability==='available';return `<div class="impact-report"><div class="impact-report-top"><span>${E(reportNames[key]||human(key))}</span>${badge(available?(r.delta===0?'Unchanged':'Changes'):'Inputs unavailable',available&&r.delta!==0?'green':'neutral')}</div><div class="impact-numbers"><strong>${available?N(r.before):'—'}</strong>${icon('arrow',22)}<strong>${available?N(r.after):'—'}</strong><span class="delta">${available?(r.delta>0?'+':'')+r.delta:'Not calculable'}</span></div><div class="impact-note">Unresolved cases: ${N(r.unresolved_before)} → ${N(r.unresolved_after)}${r.uncertainty_increased?' · Additional uncertainty requires review':''}</div><div class="impact-note">Trust score: ${r.trust_score_before??'Not measured'} → ${r.trust_score_after??'Not measured'} · ${E(readinessLabel(r.readiness_after))}</div></div>`}
function coverageHTML(sim){const c=sim.coverage;if(!c)return '';return `<div class="drawer-section coverage-panel"><h3>What this preview covers</h3><p class="text-small">Calculated: ${c.calculated_reports.map(key=>E(reportNames[key]||human(key))).join(', ')}.</p><p class="text-small">Potential system exposure: ${c.potential_only_systems.map(key=>E(sourceNames[key]||human(key))).join(', ')||'No additional system path declared'}.</p>${c.potential_only_reports.length?`<p class="text-small">Reports without executable calculations: ${c.potential_only_reports.map(E).join(', ')}.</p>`:''}<p class="text-small muted">${E(c.unmodelled_behavior)}</p></div>`}


function sourceUploadFieldsHTML(sources){return sources.map(source=>`<div class="upload-field"><label for="file-${E(source.source_system)}">${icon('file',14)} ${E(source.name)}</label><input type="file" id="file-${E(source.source_system)}" data-source="${E(source.source_system)}" accept=".csv,text/csv" aria-label="Upload ${E(source.name)} CSV"><small>${E(source.filename)}</small></div>`).join('');}
async function configureUploadSources(){
  const revision=++S.uploadRevision,target=document.querySelector('#source-config-message'),container=document.querySelector('#source-upload-fields');
  S.uploadReady=false;target.textContent='Reading the source configuration locally…';
  try{
    const file=document.querySelector('#policy-file').files[0],payload=file?{policy:JSON.parse(await file.text())}:{};
    const result=await api('/api/sources/preview',{},payload);
    if(revision!==S.uploadRevision||!target.isConnected)return;
    const selected=new Map(S.uploadSources.map(source=>[source.source_system,{filename:source.filename,input:document.querySelector('#file-'+source.source_system)}]));
    container.innerHTML=sourceUploadFieldsHTML(result.sources);
    for(const source of result.sources){const previous=selected.get(source.source_system);if(previous?.filename===source.filename&&previous.input?.files.length){previous.input.setAttribute('aria-label','Upload '+source.name+' CSV');container.querySelector('#file-'+source.source_system).replaceWith(previous.input);}}
    S.uploadSources=result.sources;S.uploadReady=true;
    target.className='text-small muted';target.textContent=`${result.sources.length} sources configured. Choose one CSV for each source; selections for unchanged sources are retained.`;
  }catch(error){if(revision===S.uploadRevision&&target.isConnected){target.className='inline-error';target.textContent=error.message;}}
}

function sourcesPage(data){S.referencePreview=null;S.referenceRevision++;S.uploadRevision++;S.uploadReady=true;S.uploadSources=S.bootstrap.upload_sources;return heading('Sources & analysis','Inspect the extracts and field mappings, or run a new analysis using synthetic source files.',`<span class="complete-pill">${icon('lock',13)} Read-only source access</span>`)+`<div class="source-grid">${data.sources.map(source=>`<section class="source-card"><div class="source-head"><span class="source-icon">${icon(source.source_system==='access_directory'?'shield':'database',17)}</span>${badge(source.status==='loaded'?'Loaded':'Review',source.status==='loaded'?'green':'amber')}</div><h2>${E(source.name)}</h2><div class="file-label">${E(source.filename)}</div><div class="source-stats"><div><strong>${N(source.records)}</strong><small>source records</small></div><div class="source-stat-side"><b>${source.issues}</b><small>findings</small></div></div><button class="mini-link" data-action="source-detail" data-value="${E(source.source_system)}">View mapping & sample ${icon('arrow',12)}</button></section>`).join('')}</div>
<div class="grid-main"><section class="card" id="new-analysis-panel"><div class="card-header"><div><h2>Run a new analysis</h2><p>Matching, determination, issue detection and report calculation</p></div>${icon('activity',18)}</div><div class="card-body"><form id="analysis-form"><div class="form-grid"><div class="form-field"><label for="analysis-mode">Source data</label><select class="input" id="analysis-mode"><option value="development">Built-in development pack</option><option value="validation">Built-in validation pack</option><option value="onboarding">Five-source onboarding demo</option><option value="upload">Upload synthetic CSVs</option></select></div><div class="form-field"><label for="analysis-date">Report date</label><input type="date" id="analysis-date" value="${E(S.overview.summary.as_of)}" required></div></div><div id="upload-section" hidden><section class="source-configuration"><h3>Sources to upload</h3><p class="text-small muted">Load a source configuration to add systems or change their file mappings. The upload fields follow its source list.</p><label for="policy-file" class="text-small">Optional source and business-rule configuration</label><input type="file" id="policy-file" accept=".json,application/json" aria-label="Upload reviewed JSON policy"><p id="source-config-message" class="text-small muted" aria-live="polite">${N(S.uploadSources.length)} sources configured from the default policy.</p></section><div class="upload-grid" id="source-upload-fields">${sourceUploadFieldsHTML(S.uploadSources)}</div><section class="reference-upload" aria-labelledby="reference-upload-title"><h3 id="reference-upload-title">Reference files</h3><p class="text-small muted">Add the supplied dictionary and dependency map. Review the extracted definitions and paths before running the analysis.</p><div class="upload-grid"><div class="upload-field"><label for="dictionary-file">${icon('file',14)} Data dictionary</label><input type="file" id="dictionary-file" accept=".md,.markdown,text/markdown,text/plain" aria-label="Upload data_dictionary.md"><small>data_dictionary.md · field definitions and valid codes</small></div><div class="upload-field"><label for="dependencies-file">${icon('branch',14)} Dependencies</label><input type="file" id="dependencies-file" accept=".md,.markdown,text/markdown,text/plain" aria-label="Upload dependencies.md"><small>dependencies.md · downstream systems and reports</small></div></div><button type="button" class="button button-small" data-action="preview-references" id="preview-references">${icon('file',14)} Preview reference files</button><div id="reference-preview" aria-live="polite"><p class="reference-hint">Without reference files, this run uses provisional demo definitions or your reviewed policy configuration.</p></div></section><label class="checkbox-label"><input type="checkbox" id="synthetic-confirm">I confirm that these files contain synthetic employee data only. They will be processed and saved in this local workspace.</label></div><div class="form-actions"><button class="button button-primary" id="start-analysis" type="submit">${icon('activity',15)} Run analysis</button><span class="muted text-small">Every run keeps its own review history.</span></div><div id="analysis-message"></div></form></div></section>
<section class="card"><div class="card-header"><div><h2>Policy in use</h2><p>${E(data.policy.policy_version)}</p></div>${icon('shield',17)}</div><div class="card-body">${referenceImportHTML(data.reference_import||data.policy.reference_import)}<div class="coverage-row"><div class="coverage-name">Employment status<small>Core HR · ${E((data.policy.sources.core_hr?.domains?.employment_status||[]).join(' / ')||'No code list declared')}</small></div></div><div class="coverage-row"><div class="coverage-name">Account status<small>Directory · ${E((data.policy.sources.access_directory?.domains?.account_status||[]).join(' / ')||'No code list declared')}</small></div></div><div class="coverage-row"><div class="coverage-name">Leaver access grace<small>${data.policy.reports.access_grace_days} days after the employment end date</small></div></div><div class="coverage-row"><div class="coverage-name">Field ownership<small>Validity and employment context checked before selection</small></div></div><details style="margin-top:16px"><summary>Authority & dependency rules</summary><div class="details-body">${Object.entries(data.policy.authority).map(([field,rule])=>`<p style="margin-bottom:8px"><b>${E(human(field))}</b> · ${rule.sources.map(s=>E(sourceNames[s]||s)).join(', ')}</p>`).join('')}<p class="muted">${data.policy.dependencies.length} explicitly declared field dependencies. Source status meanings stay separate.</p></div></details></div></section></div>${data.diagnostics.length?notice(`${N(data.diagnostics.length)} ingestion diagnostics need review. Open the source cards to inspect the affected fields.`,'warning','alert'):''}`}

function referenceDefinitionTable(definitions){return `<div class="table-wrap reference-table"><table><thead><tr><th>Source / field</th><th>Columns & meaning</th><th>Valid values</th><th>Evidence</th></tr></thead><tbody>${definitions.map(d=>`<tr><td>${E(sourceNames[d.source]||d.source)}<div class="cell-sub">${E(human(d.field))} · ${d.required?'Required':'Optional'}</div></td><td><span class="mono">${E((d.columns||[]).join(', '))}</span>${d.description?`<div class="cell-sub">${E(d.description)}</div>`:''}</td><td>${E((d.valid_values||[]).join(', ')||'No code list')}</td><td class="mono">data_dictionary.md:${E(d.line||'?')}</td></tr>`).join('')}</tbody></table></div>`}
function referenceDependencyTable(dependencies){return `<div class="table-wrap reference-table"><table><thead><tr><th>Upstream</th><th>Downstream</th><th>Evidence</th></tr></thead><tbody>${dependencies.map(d=>`<tr><td class="mono">${E(d.source)}</td><td class="mono">${E(d.target)}</td><td class="mono">dependencies.md:${E(d.line||'?')}</td></tr>`).join('')}</tbody></table></div>`}
function referenceImportHTML(imported){
if(!imported)return notice('These are provisional demo policies. Add and review the supplied dictionary and dependencies when analysing challenge files.','neutral');
const documents=Array.isArray(imported.documents)?imported.documents:Object.entries(imported.documents||{}).map(([filename,d])=>({filename,...d}));
return `<div class="reference-in-use">${notice(imported.reviewed?'Reference definitions and dependency paths were reviewed for this analysis. Field authority and report meanings still follow the selected base policy.':'Reference definitions and dependency paths were imported for this synthetic demo. Human review is not recorded; business assumptions remain provisional.','neutral')}<h3>Reference files in use</h3>${documents.map(d=>`<div class="reference-document"><strong>${E(d.filename)}</strong><small class="mono break">SHA-256 ${E(d.sha256||d.hash||'Not recorded')}</small>${['data_dictionary.md','dependencies.md'].includes(d.filename)?`<a class="mini-link reference-download" href="${download('reference_documents/'+d.filename)}">${icon('download',12)} Download source reference</a>`:''}</div>`).join('')}<a class="button button-small reference-download" href="${download('reference_import.json')}">${icon('download',13)} Export reference evidence</a>${imported.definitions?.length?`<details><summary>${N(imported.definitions.length)} imported field definitions</summary><div class="details-body">${referenceDefinitionTable(imported.definitions)}</div></details>`:''}${imported.dependencies?.length?`<details><summary>${N(imported.dependencies.length)} imported dependency paths</summary><div class="details-body">${referenceDependencyTable(imported.dependencies)}</div></details>`:''}${imported.warnings?.length?`<details><summary>Retained policy assumptions</summary><div class="details-body"><ul class="reference-changes">${imported.warnings.map(w=>`<li>${E(w)}</li>`).join('')}</ul></div></details>`:''}</div>`;
}
function invalidateReferencePreview(){S.referencePreview=null;S.referenceRevision++;const target=document.querySelector('#reference-preview');if(target)target.innerHTML='<p class="reference-hint">Reference files or policy changed. Preview them again before running the analysis.</p>';}
async function referenceFileText(file){try{return new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer())}catch{throw new Error(`${file.name} must be a UTF-8 Markdown file.`)}}
async function readReferenceInput(){const dictionary=document.querySelector('#dictionary-file')?.files[0],dependencies=document.querySelector('#dependencies-file')?.files[0],policyFile=document.querySelector('#policy-file')?.files[0];const payload={};if(policyFile)payload.policy=JSON.parse(await policyFile.text());if(dictionary||dependencies){if(!dictionary||!dependencies)throw new Error('Choose both data_dictionary.md and dependencies.md.');for(const file of [dictionary,dependencies]){if(!file.size||file.size>1024*1024)throw new Error('Each reference file must be nonempty and no larger than 1 MB.');}payload.reference_documents={'data_dictionary.md':await referenceFileText(dictionary),'dependencies.md':await referenceFileText(dependencies)};}return payload;}
function referenceDateFormats(value){if(Array.isArray(value))return value;if(typeof value==='string')return [value];return Object.entries(value||{}).map(([field,formats])=>`${human(field)}: ${Array.isArray(formats)?formats.join(', '):formats}`);}
function referenceChangeLabel(change){if(typeof change==='string')return change;if(change.description||change.message)return change.description||change.message;const prefix=change.source?(sourceNames[change.source]||human(change.source))+': ':'';const before=change.before,after=change.after;const count=value=>Array.isArray(value)?value.length:Object.keys(value||{}).length;const changedFields=()=>[...new Set([...Object.keys(before||{}),...Object.keys(after||{})])].filter(key=>JSON.stringify(before?.[key])!==JSON.stringify(after?.[key])).map(human).join(', ');if(change.section==='dependencies')return `Dependency map: ${count(before)} → ${count(after)} declared paths.`;if(change.section==='fields')return `${prefix}source column mappings updated (${count(before)} → ${count(after)} fields).`;if(change.section==='required')return `${prefix}required fields updated (${count(before)} → ${count(after)} required).`;if(change.section==='domains')return `${prefix}valid code lists updated for ${changedFields()}.`;if(change.section==='value_maps')return `${prefix}code translations updated for ${changedFields()}.`;if(change.section==='date_formats')return `${prefix}date formats: ${referenceDateFormats(before).join(', ')} → ${referenceDateFormats(after).join(', ')}.`;return `${prefix}${human(change.section)} updated.`;}
async function previewReferenceFiles(){const target=document.querySelector('#reference-preview'),button=document.querySelector('#preview-references');invalidateReferencePreview();const revision=S.referenceRevision;button.disabled=true;target.innerHTML='<p class="reference-hint">Reading the reference files locally…</p>';try{const payload=await readReferenceInput();if(!payload.reference_documents)throw new Error('Choose data_dictionary.md and dependencies.md to preview.');const result=await api('/api/references/preview',{},payload);if(revision!==S.referenceRevision||!target.isConnected)return;S.referencePreview=result;const definitions=result.definitions||[],dependencies=result.dependencies||[];target.innerHTML=`<div class="reference-preview-head"><h3>${result.ready?'Reference files ready for review':'Reference files need attention'}</h3>${badge(`${N(definitions.length)} fields · ${N(dependencies.length)} paths`,result.ready?'green':'amber')}</div>${(result.errors||[]).map(message=>notice(E(message),'error','alert')).join('')}${(result.warnings||[]).map(message=>notice(E(message),'warning','info')).join('')}<div class="reference-documents">${(result.documents||[]).map(d=>`<div class="reference-document"><strong>${E(d.filename)}</strong><small>${N(d.line_count)} lines · SHA-256 <span class="mono break">${E(d.sha256)}</span></small></div>`).join('')}</div>${definitions.length?`<details open><summary>Field definitions & valid codes (${N(definitions.length)})</summary><div class="details-body">${referenceDefinitionTable(definitions)}</div></details>`:''}${dependencies.length?`<details><summary>Systems & report paths (${N(dependencies.length)})</summary><div class="details-body">${referenceDependencyTable(dependencies)}</div></details>`:''}${result.changes?.length?`<details><summary>Changes from the selected policy (${N(result.changes.length)})</summary><div class="details-body"><ul class="reference-changes">${result.changes.map(change=>`<li>${E(referenceChangeLabel(change))}</li>`).join('')}</ul></div></details>`:''}${result.ready?'<label class="checkbox-label"><input type="checkbox" id="references-reviewed">I reviewed these definitions, valid codes, dependency paths and retained policy assumptions for this analysis.</label>':'<p class="inline-error">Correct the flagged reference entries or supply a supported table layout, then preview again.</p>'}`;}catch(error){if(revision===S.referenceRevision&&target.isConnected)target.innerHTML=notice(E(error.message),'error','alert');}finally{if(button.isConnected)button.disabled=false;}}

function auditPage(data){const cards=[['issues.csv','Ranked findings','Complete issue queue · CSV'],['employees.csv','Employee matches','Source-to-person links · CSV'],['reports.json','Report evidence','Definitions and contributors · JSON'],['impact_simulations.json','Impact previews','Calculated correction scenarios · JSON'],['field_trust.csv','Field quality','Measured indicators · CSV'],['decisions.jsonl','Decision history','Hash-chained review events · JSONL']];return heading('Decisions & exports','A traceable record of human review. Decisions never execute corrections or modify employee records.',`<span class="integrity-label">${icon('shield',15)} History integrity verified</span>`)+`<section class="card"><div class="card-header"><div><h2>Review history</h2><p>${N(data.events.length)} recorded decisions in this analysis</p></div>${data.events.length?`<a class="button button-small" href="${download('decisions.jsonl')}">${icon('download',14)} Export history</a>`:''}</div>${data.events.length?`<div class="table-wrap"><table><thead><tr><th>When</th><th>Finding</th><th>Reviewer</th><th>Decision</th><th>Rationale</th></tr></thead><tbody>${data.events.map(event=>`<tr><td><div class="cell-title">${E(new Date(event.recorded_at).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}))}</div><div class="cell-sub">${E(new Date(event.recorded_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}))}</div></td><td><button class="link-button mono" data-issue="${E(event.issue_id)}">${E(event.issue_id.slice(0,16))}…</button></td><td class="cell-title">${E(event.reviewer)}</td><td>${statusHTML(event.decision)}</td><td class="audit-reason">${E(event.reason)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your review history starts here','Open a finding, inspect its evidence and preview the impact. Your decision and rationale will be saved here.','<button class="button button-primary" data-route="issues">Open issue queue '+icon('arrow',14)+'</button>')}<div class="card-note">Local history is hash chained for tamper evidence. Reviewer authentication and protected enterprise storage are pilot integrations.</div></section><div class="section-space"><div class="page-heading" style="margin-bottom:16px"><div><h2>Analysis exports</h2><p>Download the results and evidence for this snapshot.</p></div></div><div class="export-grid">${cards.map(([file,title,sub])=>`<div class="export-card">${icon('file',23)}<div><strong>${title}</strong><small>${sub}</small></div>${file==='decisions.jsonl'&&!data.events.length?`<button class="icon-button" disabled aria-label="Decision history is empty">${icon('download',17)}</button>`:`<a class="icon-button" href="${download(file)}" aria-label="Download ${E(title)}">${icon('download',17)}</a>`}</div>`).join('')}</div></div>`}

let returnFocus=null;
function drawerShell(title,subtitle,content,tabs=''){document.querySelector('#drawer-root').innerHTML=`<div class="drawer-scrim" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-header"><div class="drawer-topline"><span class="eyebrow" style="margin:0">${E(S.drawer?.kind==='issue'?'FINDING REVIEW':S.drawer?.kind==='employee'?'EMPLOYEE EVIDENCE':'WORKSPACE EVIDENCE')}</span><button class="icon-button" data-action="close-drawer" aria-label="Close detail panel">${icon('close',20)}</button></div><h2 id="drawer-title">${title}</h2><p>${subtitle}</p></div>${tabs}<div class="drawer-scroll">${content}</div></aside>`;document.body.style.overflow='hidden';}
function closeDrawer(){S.drawer=null;document.querySelector('#drawer-root').replaceChildren();document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus()}
function rawRecords(records){return records.map(r=>`<details><summary>${E(sourceNames[r.source_system]||r.source_system)} · ${E(r.source_id||'No identifier')} ${r.assignment?`<span class="muted">· evidence score ${Math.round(r.assignment.score*100)}/100</span>`:''}</summary><div class="details-body"><div class="table-wrap"><table class="raw-table"><tbody>${Object.entries(r.raw).map(([key,value])=>`<tr><td>${E(key)}</td><td>${E(pretty(value))}</td></tr>`).join('')}</tbody></table></div>${r.assignment?`<div style="margin-top:12px">${r.assignment.evidence.map(reason=>`<p style="margin-top:5px">${E(reason)}</p>`).join('')}</div>`:''}</div></details>`).join('')}
async function openIssue(id){returnFocus=document.activeElement;S.drawer={kind:'issue',id,tab:'evidence',data:null,simulation:S.simulations.get(S.run+id)||null};drawerShell('Loading finding…','Preparing the supporting records.',loading());try{const data=await api('/api/issue',{id});if(S.drawer?.id!==id)return;S.drawer.data=data;renderIssueDrawer();document.querySelector('.drawer [data-action="close-drawer"]').focus()}catch(error){drawerShell('Finding unavailable','The finding could not be loaded.',notice(E(error.message),'error','alert'))}}
function renderIssueDrawer(){const d=S.drawer;if(!d?.data)return;const i=d.data.issue;const tabs=`<div class="tabs drawer-tabs" role="tablist">${[['evidence','Evidence'],['impact','Impact preview'],['decision','Review decision']].map(([key,label])=>`<button class="tab ${d.tab===key?'active':''}" data-action="drawer-tab" data-value="${key}" role="tab" aria-selected="${d.tab===key}">${label}${key==='impact'&&d.simulation?icon('check',12):''}</button>`).join('')}</div>`;let content='';
if(d.tab==='evidence'){
const observations=d.data.records.map(r=>{const columns=r.field_columns?.[i.field]||[];let raw=columns.length?r.raw[columns[0]]:r.values[i.field];let displayed=columns.length||raw!==undefined&&raw!==null?pretty(raw):'Not a field in this source';if(i.issue_type==='possible_ghost_access'&&r.source_system==='core_hr')displayed=`${pretty(r.values.employment_status)} · end date ${pretty(r.values.termination_date)}`;else if(i.issue_type==='possible_ghost_access'&&r.source_system==='payroll')displayed=`Payroll state: ${pretty(r.values.payroll_status)}`;else if(i.issue_type==='possible_ghost_access'&&r.source_system==='learning')displayed='Learning profile; not an employment-status source';return `<tr class="${r.record_id===i.record_id?'evidence-row-target':''}"><td>${sourceTag(r.source_system)}<div class="cell-sub">…${E(shortID(r.source_id))}</div></td><td class="break">${E(displayed)}</td><td class="evidence-role">${r.record_id===i.record_id?'Target record':d.data.resolutions.some(res=>res.evidence.includes(r.record_id))?'Authority evidence':r.supports_issue?'Supports finding':'Matched observation'}</td></tr>`}).join('');
content=`<div class="drawer-section"><div class="tag-row" style="margin-bottom:13px">${priority(i.priority_band)}${badge(human(i.business_impact),'amber')}${statusHTML(i.review_status)}</div><p class="explanation">${E(i.evidence.explanation)}</p><div class="comparison"><div><label>Observed value</label><strong>${E(pretty(i.observed_value))}</strong><small>${E(sourceNames[i.source_system])} · ${E(human(i.field))}</small></div><div><label>${i.recommendation_status==='proposed'?'Proposed value':'Determination'}</label><strong>${E(i.suggested_value||'Investigation required')}</strong><small>${i.recommendation_status==='proposed'?'Supported by the configured policy':'No supported replacement established'}</small></div></div><div class="meta-grid"><div class="meta-item"><label>Business priority</label><strong>${i.priority_score} / 100</strong><small>${E(human(i.severity))} severity</small></div><div class="meta-item"><label>Identity evidence</label><strong>${Math.round(i.match_confidence*100)} / 100</strong><small>Evidence score, not probability</small></div><div class="meta-item"><label>Correction state</label><strong>${i.recommendation_status==='proposed'?'Proposed':'Unresolved'}</strong><small>Human decision required</small></div></div></div><div class="drawer-section"><h3>Compare source observations</h3><div class="evidence-table table-wrap"><table><thead><tr><th>Source</th><th>${E(comparisonHeading(i))}</th><th>Role</th></tr></thead><tbody>${observations}</tbody></table></div></div><div class="drawer-section"><h3>Why this priority?</h3><ul class="reason-list">${i.priority_reasons.map(reason=>`<li>${icon('check',13)}${E(reason)}</li>`).join('')}</ul></div><div class="drawer-section"><h3>Determination & rule</h3>${d.data.resolutions.length?d.data.resolutions.map(res=>`<details><summary>${E(human(res.field))} · ${E(human(res.status))}</summary><div class="details-body"><p>${E(res.reason)}</p><p class="mono" style="margin-top:8px">${E(res.rule_id)} · ${E(res.policy_version)}</p></div></details>`).join(''):notice('This finding follows a source validation or lifecycle rule. No cross-system authoritative replacement is inferred.','neutral')}<p class="text-small muted" style="margin-top:10px">Rule ${E(i.rule_id)} · Policy ${E(i.policy_version)}</p></div><div class="drawer-section"><h3>Original records & matching evidence</h3>${rawRecords(d.data.records)}</div><button class="button button-primary" style="width:100%" data-action="go-impact">${i.recommendation_status==='proposed'?'Preview the effect of this correction':'View impact limitations'} ${icon('arrow',15)}</button>`;
}else if(d.tab==='impact'){
if(i.recommendation_status!=='proposed')content=notice('This finding has no supported replacement value. Investigate the evidence before creating a correction scenario.','warning','alert')+`<div class="section-space"><button class="button" data-action="go-decision">Record an investigation decision ${icon('arrow',14)}</button></div>`;
else if(d.simulating)content='<div class="loading-state" style="min-height:300px"><span class="spinner"></span><h2>Calculating the correction scenario</h2><p>Recomputing the implemented reports in an isolated copy of the snapshot.</p></div>';
else if(!d.simulation)content=`<div class="preview-start"><div class="preview-icon">${icon('branch',39)}</div><h2>See the effect before deciding</h2><p>The engine changes this one value in an isolated scenario and runs the same report calculations again.</p><button class="button button-primary" data-action="simulate">Calculate impact preview ${icon('arrow',14)}</button></div>`+notice('This preview never writes to source files or propagates a change into another HR system.','neutral','lock');
else{const sim=d.simulation;content=notice('Isolated scenario calculated. Source files are unchanged.','','check')+`<div class="comparison"><div><label>Current ${E(human(i.field))}</label><strong>${E(pretty(sim.patch.expected_value))}</strong></div><div><label>Proposed ${E(human(i.field))}</label><strong>${E(pretty(sim.patch.value))}</strong></div></div><div class="drawer-section"><h3>Calculated report effects</h3>${Object.entries(sim.reports).map(([key,result])=>impactReportHTML(key,result)).join('')}</div><div class="drawer-section"><h3>Systems & reports in the dependency map</h3><div class="dependency-flow"><div class="dependency-node target">${icon('database',16)} ${E(sourceNames[sim.target_system]||sim.target_system)} · ${E(human(i.field))}</div>${sim.potential_dependencies.map(node=>`<div class="dependency-node dependency-child">${icon(node.startsWith('report:')?'chart':'database',15)} ${E(node.startsWith('report:')?(reportNames[node.slice(7)]||human(node.slice(7))):node)}</div>`).join('')}${!sim.potential_dependencies.length?'<p class="text-small muted">No downstream path is declared for this field.</p>':''}</div><p class="text-small muted" style="margin-top:12px;line-height:1.8">A dependency indicates potential exposure. Only the report calculations above have a measured numerical effect; downstream systems are never updated.</p></div>${coverageHTML(sim)}<button class="button button-primary" style="width:100%" data-action="go-decision">Review this proposal ${icon('arrow',15)}</button>`}
}else{
content=(i.last_decision?`<div class="decision-card"><strong>${E({approve:'Proposal approved',reject:'Proposal rejected',investigate:'Investigation requested'}[i.last_decision.decision])}</strong><p>${E(i.last_decision.reviewer)} · ${E(new Date(i.last_decision.recorded_at).toLocaleString())}</p><p>${E(i.last_decision.reason)}</p></div>`:'')+notice('Your decision is recorded against this snapshot and policy. Approval does not execute a correction or change source data.','neutral','lock')+`<form id="decision-form" style="margin-top:21px"><div class="form-grid"><div class="form-field form-wide"><label for="review-decision">Decision</label><select id="review-decision" class="input"><option value="approve" ${i.recommendation_status!=='proposed'?'disabled':''}>Approve proposal</option><option value="reject">Reject proposal</option><option value="investigate" ${i.recommendation_status!=='proposed'?'selected':''}>Needs investigation</option></select></div><div class="form-field form-wide"><label for="reviewer-name">Reviewer name</label><input type="text" id="reviewer-name" value="${E(localStorage.getItem('hr-reviewer')||'')}" placeholder="Enter your name" required maxlength="120" autocomplete="name"></div><div class="form-field form-wide"><label for="review-reason">Rationale</label><textarea id="review-reason" placeholder="Explain the evidence or exception behind your decision…" required maxlength="3000"></textarea></div></div>${i.recommendation_status==='proposed'&&!d.simulation?`<div style="margin-top:16px">${notice('Preview the correction impact before approving this proposal. You can still reject it or request investigation.','warning','info')}<button type="button" class="button button-small" style="margin-top:12px" data-action="go-impact">Open impact preview ${icon('arrow',13)}</button></div>`:''}<div class="form-actions"><button type="submit" class="button button-primary" id="save-decision">Record decision ${icon('check',14)}</button></div><div id="decision-message"></div></form>`;
}
drawerShell(`${E(issueNames[i.issue_type]||human(i.issue_type))}`,`${E(i.employee_name)} · ${E(sourceNames[i.source_system])} · ${E(human(i.field))}`,content,tabs);
}
async function simulateIssue(){if(!S.drawer?.data)return;const id=S.drawer.id;S.drawer.simulating=true;renderIssueDrawer();try{const sim=await api('/api/simulate',{}, {issue_id:id});if(S.drawer?.id!==id)return;S.simulations.set(S.run+id,sim);S.drawer.simulation=sim;S.drawer.simulating=false;renderIssueDrawer()}catch(error){if(S.drawer?.id===id){S.drawer.simulating=false;renderIssueDrawer()}toast(error.message,true)}}
async function openEmployee(id){returnFocus=document.activeElement;S.drawer={kind:'employee',id};drawerShell('Loading employee evidence…','Retrieving source observations.',loading());try{const d=await api('/api/employee',{id});if(S.drawer?.id!==id)return;const content=`<div class="drawer-section"><div class="tag-row">${d.employee.sources.map(sourceTag).join('')}${badge(d.employee.status==='linked'?'Linked identity':human(d.employee.status),d.employee.status==='linked'?'green':'amber')}</div><p class="text-small muted" style="margin-top:13px;line-height:1.8">${d.records.length} source observations belong to this inferred person group. Employment IDs remain local to their source and may represent different assignments.</p></div><div class="drawer-section"><h3>Source records & identity evidence</h3>${rawRecords(d.records)}</div><div class="drawer-section"><h3>Field determinations</h3>${d.resolutions.length?`<div class="evidence-table table-wrap"><table><thead><tr><th>Field</th><th>Selected value</th><th>State</th></tr></thead><tbody>${d.resolutions.map(r=>`<tr><td>${E(human(r.field))}<div class="cell-sub">Context …${E(shortID(r.employment_context))}</div></td><td>${E(resolvedValue(r))}</td><td>${badge(human(r.status),r.status==='resolved'?'green':'amber')}</td></tr>`).join('')}</tbody></table></div>`:notice('No authoritative employment context is established for these observations.','neutral')}</div><div class="drawer-section"><h3>Matching candidates</h3><p class="text-small muted" style="margin-bottom:12px">Evidence scores are not calibrated probabilities. Showing up to 30 candidates.</p>${d.candidates.map(c=>`<div class="candidate-card"><div class="candidate-top"><strong>${E(sourceNames[c.source_system_a]||c.source_system_a)} ↔ ${E(sourceNames[c.source_system_b]||c.source_system_b)}</strong>${badge(`${Math.round(c.score*100)} / 100 · ${human(c.status)}`,c.status==='accepted'?'green':'neutral')}</div><p>${c.evidence.map(E).join(' ')}</p></div>`).join('')||'<p class="text-small muted">No supported cross-source candidates are available.</p>'}</div>${d.issues.length?`<div class="drawer-section"><h3>Findings for this employee</h3>${d.issues.map(i=>`<button class="button" style="width:100%;justify-content:space-between;margin-bottom:8px" data-issue="${E(i.issue_id)}"><span>${priority(i.priority_band)} ${E(issueNames[i.issue_type])}</span>${icon('arrow',14)}</button>`).join('')}</div>`:''}`;drawerShell(E(d.employee.name),`${E(id)} · ${d.employee.record_count} records`,content);document.querySelector('.drawer [data-action="close-drawer"]').focus()}catch(error){drawerShell('Employee evidence unavailable','',notice(E(error.message),'error','alert'))}}
function openSource(source){returnFocus=document.activeElement;S.drawer={kind:'source',id:source};const d=S.sourceData.sources.find(s=>s.source_system===source);const content=`<div class="drawer-section"><div class="tag-row">${badge(`${N(d.records)} records`,'green')}${badge(`${d.fields} source fields`)}${badge(`${d.issues} findings`,'amber')}</div><p class="text-small muted" style="margin-top:14px;line-height:1.8">${E(d.record_grain)}. Declared date formats: ${referenceDateFormats(d.date_formats).map(E).join(', ')}.</p></div><div class="drawer-section"><h3>Explicit field mappings</h3><div class="evidence-table table-wrap"><table><thead><tr><th>Semantic field</th><th>Source columns</th><th>Required</th></tr></thead><tbody>${Object.entries(d.mapping).map(([field,aliases])=>`<tr><td>${E(human(field))}</td><td class="mono">${aliases.map(E).join(', ')}</td><td>${d.required.includes(field)?badge('Required','green'):'<span class="muted">Optional</span>'}</td></tr>`).join('')}</tbody></table></div></div>${Array.isArray(d.definitions)&&d.definitions.length?`<div class="drawer-section"><h3>Imported field definitions</h3>${referenceDefinitionTable(d.definitions)}</div>`:''}${d.diagnostics.length?`<div class="drawer-section"><h3>Ingestion diagnostics</h3>${d.diagnostics.map(x=>notice(E(x.message||human(x.code)),'warning','alert')).join('')}</div>`:''}<div class="drawer-section"><h3>Original source sample</h3><p class="text-small muted" style="margin-bottom:13px">Five source observations, shown as supplied.</p>${rawRecords(d.sample.map((raw,index)=>({raw,source_system:source,source_id:raw[d.mapping.source_id?.[0]]||`Sample ${index+1}`})))}</div>`;drawerShell(E(d.name),`${E(d.filename)} · read-only source extract`,content);}
function openReport(key){returnFocus=document.activeElement;S.drawer={kind:'report',id:key};const r=S.reports[key];const content=`${notice(E(r.definition),'neutral','info')}${assuranceHTML(r)}<div class="comparison"><div><label>Confirmed result</label><strong>${r.availability==='available'?N(r.value):'Unavailable'}</strong><small>${E(r.unit)}</small></div><div><label>Needs review</label><strong>${N(r.unresolved_count)}</strong><small>Identity or employment uncertainty</small></div></div>${r.cases?.length?`<div class="drawer-section"><h3>Payroll profile evidence</h3><p class="text-small muted">Showing up to 100 profiles. The report export includes every discrepancy and unresolved case.</p>${r.cases.map(item=>`<div class="candidate-card"><strong class="mono break">${E(item.record_id)}</strong><p>Established mismatches: ${item.mismatched_fields.map(field=>E(human(field))).join(', ')||'None established'}</p>${item.unresolved_fields.length?`<p>${E(item.unresolved_fields.join('; '))}</p>`:''}<button class="link-button" data-employee="${E(item.person_id)}">Inspect employee evidence →</button></div>`).join('')}</div>`:''}<div class="drawer-section"><h3>Contributing observations</h3><p class="text-small muted" style="margin-bottom:12px">Showing ${r.contributors.length} of ${N(r.contributor_count)} contributing records. The report export contains every contributor.</p><details><summary>Inspect contributing record references</summary><div class="details-body">${r.contributor_details?.length?r.contributor_details.map(item=>`<div class="candidate-card"><strong>${E(item.name||item.source_id)}</strong><p>${E(sourceNames[item.source_system]||item.source_system)} · ${E(item.source_id)}</p><p class="mono break">${E(item.record_id)}</p><button class="link-button" data-employee="${E(item.person_id)}">Inspect contributing employee →</button></div>`).join(''):r.contributors.map(E).join('<br>')}</div></details></div><div class="drawer-section"><h3>Unresolved cases</h3><p class="text-small muted" style="margin-bottom:12px">Showing up to 100 cases. These are not silently treated as inactive or ineligible.</p>${r.unresolved.map(u=>`<div class="candidate-card"><div class="candidate-top"><strong>${E(u.person_id||u.record_id)}</strong>${badge('Review','amber')}</div><p>${E(u.reason)}</p>${u.person_id?`<button class="link-button" style="margin-top:8px;font-size:10px" data-employee="${E(u.person_id)}">Inspect employee evidence →</button>`:''}</div>`).join('')||'<p class="text-small muted">No unresolved cases in this report.</p>'}</div><a class="button" href="${download('reports.json')}">${icon('download',14)} Export complete report evidence</a>`;drawerShell(E(reportNames[key]),`As of ${dateLabel(r.as_of)} · ${E(r.policy_version)}`,content);}

async function pollJob(job,firstRun=false){S.job=job;const show=()=>{const target=document.querySelector('#analysis-message');const html=`<div class="analysis-progress"><div class="analysis-progress-head"><span class="spinner"></span>${E(job.stage)}</div><p>Processing locally. You can keep this window open; source files will stay unchanged.</p></div>`;if(target)target.innerHTML=html;else if(firstRun)document.querySelector('#main').innerHTML=`<div class="loading-state"><span class="spinner"></span><h2>Preparing your first workspace</h2><p>${E(job.stage)}</p><p>The built-in synthetic data is being analysed locally.</p></div>`};show();while(job.status==='running'){await new Promise(resolve=>setTimeout(resolve,1000));job=await api('/api/job',{id:job.id});show()}
S.job=null;if(job.status==='failed')throw new Error(job.error||'Analysis could not complete.');S.bootstrap=await api('/api/bootstrap');S.run=job.run;localStorage.setItem('hr-run',S.run);S.simulations.clear();S.route='overview';await loadRun();location.hash='overview';toast('Analysis complete. Your new workspace is ready.');}
async function fileBase64(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary)}

document.addEventListener('click',async event=>{const button=event.target.closest('[data-action],[data-route],[data-issue],[data-employee]');if(!button)return;try{
if(button.dataset.route){navigate(button.dataset.route);return}
if(button.dataset.issue){await openIssue(button.dataset.issue);return}
if(button.dataset.employee){await openEmployee(button.dataset.employee);return}
const action=button.dataset.action,value=button.dataset.value;
if(action==='new-analysis'){navigate('sources');setTimeout(()=>document.querySelector('#new-analysis-panel')?.scrollIntoView({behavior:'smooth',block:'start'}),250)}
else if(action==='retry')await loadRun();
else if(action==='close-drawer')closeDrawer();
else if(action==='issue-tab'){S.issueFilter=value;S.issuePage=1;document.querySelectorAll('[data-action="issue-tab"]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-selected',b===button)});await refreshIssues()}
else if(action==='paginate'){if(button.dataset.list==='issues'){S.issuePage=Number(value);await refreshIssues()}else{S.employeePage=Number(value);await refreshEmployees()}}
else if(action==='drawer-tab'){S.drawer.tab=value;renderIssueDrawer()}
else if(action==='go-impact'){S.drawer.tab='impact';renderIssueDrawer()}
else if(action==='go-decision'){S.drawer.tab='decision';renderIssueDrawer()}
else if(action==='simulate')await simulateIssue();
else if(action==='preview-references')await previewReferenceFiles();
else if(action==='source-detail')openSource(value);
else if(action==='report-detail')openReport(value);
else if(action==='report-tab'){document.querySelectorAll('[data-action="report-tab"]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-selected',b===button)});document.querySelector('#report-results').hidden=value!=='results';document.querySelector('#report-quality').hidden=value!=='quality'}
else if(action==='example-question'){document.querySelector('#question-input').value=value;document.querySelector('#question-form').requestSubmit()}
}catch(error){toast(error.message,true)}});

document.addEventListener('submit',async event=>{const form=event.target;if(!['analysis-form','decision-form','question-form'].includes(form.id))return;event.preventDefault();try{
if(form.id==='question-form'){const btn=form.querySelector('button');btn.disabled=true;try{const answer=await api('/api/question',{}, {question:document.querySelector('#question-input').value});document.querySelector('#question-answer').innerHTML=`<div class="question-answer"><span class="eyebrow" style="margin-bottom:7px">${E(reportNames[answer.report_id])}</span><div class="answer-number">${answer.answer===null?'Unavailable':N(answer.answer)}</div><div class="tag-row" style="margin-top:10px">${answer.sources.map(sourceTag).join('')}${badge(`As of ${dateLabel(answer.as_of)}`)}</div><p>${E(answer.definition)}</p>${answer.assurance?assuranceHTML({assurance:answer.assurance}):''}<p><b>${N(answer.unresolved_cases)} cases require review.</b> This is the confirmed count from the selected sources, with uncertainty retained.</p></div>`}finally{btn.disabled=false}}
else if(form.id==='decision-form'){const d=S.drawer,id=d.id,decision=document.querySelector('#review-decision').value,reviewer=document.querySelector('#reviewer-name').value.trim(),reason=document.querySelector('#review-reason').value.trim();if(decision==='approve'&&!d.simulation){document.querySelector('#decision-message').innerHTML='<p class="inline-error">Calculate the impact preview before approving the proposal.</p>';return}const btn=document.querySelector('#save-decision');btn.disabled=true;try{await api('/api/decision',{}, {issue_id:id,decision,reviewer,reason});localStorage.setItem('hr-reviewer',reviewer);d.data=await api('/api/issue',{id});S.overview=await api('/api/overview');for(const source of S.overview.sources)sourceNames[source.source_system]=source.name;renderNav();renderIssueDrawer();await renderPage();toast('Decision recorded. Source records are unchanged.')}catch(error){btn.disabled=false;throw error}}
else if(form.id==='analysis-form'){const mode=document.querySelector('#analysis-mode').value;const payload={mode,as_of:document.querySelector('#analysis-date').value,synthetic_confirmed:mode!=='upload'||document.querySelector('#synthetic-confirm').checked};if(!payload.synthetic_confirmed)throw new Error('Please confirm that the uploaded files contain synthetic data only.');if(mode==='upload'){if(!S.uploadReady)throw new Error('Load a valid source configuration before selecting CSVs.');payload.files={};for(const source of S.uploadSources){const key=source.source_system;const file=document.querySelector(`#file-${key}`).files[0];if(!file)throw new Error(`Choose the ${source.name} CSV file (${source.filename}).`);if(file.size>12*1024*1024)throw new Error(`${source.name} is larger than 12 MB.`);payload.files[key]=await fileBase64(file)}const referenceInput=await readReferenceInput();Object.assign(payload,referenceInput);if(referenceInput.reference_documents){if(!S.referencePreview?.ready||!document.querySelector('#references-reviewed')?.checked)throw new Error('Preview and review the dictionary and dependencies before running this analysis.');payload.reference_digest=S.referencePreview.digest;payload.references_reviewed=true}}const btn=document.querySelector('#start-analysis');btn.disabled=true;try{const job=await api('/api/analyze',{},payload);await pollJob(job)}catch(error){btn.disabled=false;throw error}}
}catch(error){const target=document.querySelector(form.id==='question-form'?'#question-answer':form.id==='analysis-form'?'#analysis-message':'#decision-message');if(target)target.innerHTML=`<p class="inline-error">${E(error.message)}</p>`;else toast(error.message,true)}});

let searchTimer;
document.addEventListener('input',event=>{if(!['issue-search','employee-search'].includes(event.target.id))return;clearTimeout(searchTimer);const kind=event.target.id;searchTimer=setTimeout(async()=>{try{if(kind==='issue-search'){S.issuePage=1;await refreshIssues()}else{S.employeePage=1;await refreshEmployees()}}catch(error){toast(error.message,true)}},250)});
document.addEventListener('change',async event=>{try{const id=event.target.id;if(id==='run-select'){closeDrawer();S.run=event.target.value;localStorage.setItem('hr-run',S.run);S.simulations.clear();S.sourceData=null;S.reports=null;await loadRun()}else if(['issue-priority','issue-source','issue-type','issue-status'].includes(id)){S.issuePage=1;await refreshIssues()}else if(id==='employee-status'){S.employeePage=1;await refreshEmployees()}else if(id==='analysis-mode'){document.querySelector('#upload-section').hidden=event.target.value!=='upload'}else if(id==='policy-file'){invalidateReferencePreview();await configureUploadSources()}else if(['dictionary-file','dependencies-file'].includes(id))invalidateReferencePreview()}catch(error){toast(error.message,true)}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeDrawer();document.querySelector('#sidebar').classList.remove('open')}const row=event.target.closest('tr[data-issue],tr[data-employee]');if(row&&(event.key==='Enter'||event.key===' ')){event.preventDefault();row.click()}if(event.key==='Tab'&&S.drawer){const elements=[...document.querySelectorAll('.drawer button:not([disabled]),.drawer a[href],.drawer input,.drawer select,.drawer textarea')].filter(x=>x.getClientRects().length);if(!elements.length)return;const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{if(location.hash==='#main')return;S.route=location.hash.slice(1)||'overview';window.scrollTo(0,0);renderPage()});
document.querySelector('#menu-toggle').innerHTML=icon('menu',19);document.querySelector('#menu-toggle').addEventListener('click',()=>{const open=document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open))});document.querySelector('#local-symbol').innerHTML=icon('shield',20);

(async()=>{try{S.bootstrap=await api('/api/bootstrap');if(!S.bootstrap.runs.length){const job=await api('/api/analyze',{}, {mode:'development',as_of:'2026-10-01',synthetic_confirmed:true});await pollJob(job,true);return}if(!S.bootstrap.runs.some(r=>r.id===S.run))S.run=S.bootstrap.runs[0].id;S.route=location.hash.slice(1)||'overview';await loadRun()}catch(error){document.querySelector('#main').innerHTML=empty('The workspace could not start',error.message,'<button class="button" data-action="retry">Try again</button>')}})();
